INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(195,'Regra Geral','LC 214/2025','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO I \n\nDAS NORMAS GERAIS DO IBS E DA CBS \n\nCAPÍTULO I \n\nDISPOSIÇÕES PRELIMINARES','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(196,'Art. 128. Desde que observadas as definições e demais disposições deste Capítulo, ficam reduzidas em 60% (sessenta por cento) as alíquotas do IBS e da CBS incidentes sobre operações com:\nI - serviços de educação;\nII - serviços de saúde;\nVIII - produtos agropecuários, aquícolas, pesqueiros, florestais e extrativistas vegetais in natura;\nIX - insumos agropecuários e aquícolas;\nX - produções nacionais artísticas, culturais, de eventos, jornalísticas e audiovisuais;\nXI - comunicação institucional;\nXII - atividades desportivas; e\nXIII - bens e serviços relacionados à soberania e à segurança nacional, à segurança da informação e à segurança cibernética.','Art. 128, I, II, VIII, IX, X, XI, XII e XIII','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO IV\n\nDOS REGIMES DIFERENCIADOS DO IBS E DA CBS\n\nCAPÍTULO III\n\nDA REDUÇÃO EM SESSENTA POR CENTO DAS ALÍQUOTAS DO IBS E DA CBS\n\nSeção I\n\nDisposições Gerais','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(197,'Art. 127. Ficam reduzidas em 30% (trinta por cento) as alíquotas do IBS e da CBS incidentes sobre a prestação de serviços pelos seguintes profissionais, que exercerem atividades intelectuais de natureza científica, literária ou artística, submetidas à fiscalização por conselho profissional: \n I – administradores;\n II – advogados;\n III – arquitetos e urbanistas;\n IV – assistentes sociais;\n V – bibliotecários;\n VI – biólogos;\n VII – contabilistas;\n VIII – economistas;\n IX – economistas domésticos;\n X – profissionais de educação física;\n XI – engenheiros e agrônomos;\n XII – estatísticos;\n XIII - médicos veterinários e zootecnistas;\n XIV – museólogos;\n XV – químicos;\n XVI – profissionais de relações públicas;\n XVII – técnicos industriais; e\n XVIII – técnicos agrícolas;','Art. 127','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO IV\n\nDOS REGIMES DIFERENCIADOS DO IBS E DA CBS\n\nCAPÍTULO II\n\nDA REDUÇÃO EM TRINTA POR CENTO DAS ALÍQUOTAS DO IBS E DA CBS','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(198,'Art. 94. São isentas do pagamento do IBS e da CBS na importação de bens materiais:\nI - bagagens de viajantes e de tripulantes, acompanhadas ou desacompanhadas; e','Art. 94 I','LIVRO I\n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS)\n\nTÍTULO II\n\nDOS REGIMES ADUANEIROS ESPECIAIS E DOS REGIMES DE BAGAGEM, DE REMESSAS INTERNACIONAIS E DE FORNECIMENTO DE COMBUSTÍVEL PARA AERONAVES EM TRÁFEGO INTERNACIONAL\n\nCAPÍTULO I\n\nDOS REGIMES ADUANEIROS ESPECIAIS\n\nSeção VI\n\nDos Regimes de Bagagem e de Remessas Internacionais','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(199,'Art. 94. São isentas do pagamento do IBS e da CBS na importação de bens materiais:\nII - remessas internacionais, desde que:\na) sejam isentas do Imposto sobre a Importação;\nb) o remetente e o destinatário sejam pessoas físicas; e\nc) não tenha ocorrido a intermediação de plataforma digital.','Art. 94 II','LIVRO I\n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS)\n\nTÍTULO II\n\nDOS REGIMES ADUANEIROS ESPECIAIS E DOS REGIMES DE BAGAGEM, DE REMESSAS INTERNACIONAIS E DE FORNECIMENTO DE COMBUSTÍVEL PARA AERONAVES EM TRÁFEGO INTERNACIONAL\n\nCAPÍTULO I\n\nDOS REGIMES ADUANEIROS ESPECIAIS\n\nSeção VI\n\nDos Regimes de Bagagem e de Remessas Internacionais','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(200,'Art. 89.\n§ 3º O disposto no caput deste artigo não se aplica:\nII - até a data estabelecida pelo art. 92-A do Ato das Disposições Constitucionais Transitórias, aos bens importados temporariamente e para utilização econômica por empresas que se enquadrem nas disposições do Decreto-Lei nº 288, de 28 de fevereiro de 1967, durante o período de sua permanência na Zona Franca de Manaus, os quais serão submetidos ao regime de admissão temporária com suspensão total do pagamento dos tributos.','Art. 89, § 3º, II','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO II\n\nDOS REGIMES ADUANEIROS ESPECIAIS E DOS REGIMES DE BAGAGEM, DE REMESSAS INTERNACIONAIS E DE FORNECIMENTO DE COMBUSTÍVEL PARA AERONAVES EM TRÁFEGO INTERNACIONAL\n\nCAPÍTULO I\n\nDOS REGIMES ADUANEIROS ESPECIAIS\n\nSeção III\n\nDos Regimes de Permanência Temporária','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(201,'Art. 90. Fica suspenso o pagamento do IBS e da CBS incidentes na importação enquanto os bens materiais estiverem submetidos a regime aduaneiro especial de aperfeiçoamento, observada a disciplina estabelecida na legislação aduaneira.','Art. 90','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO II\n\nDOS REGIMES ADUANEIROS ESPECIAIS E DOS REGIMES DE BAGAGEM, DE REMESSAS INTERNACIONAIS E DE FORNECIMENTO DE COMBUSTÍVEL PARA AERONAVES EM TRÁFEGO INTERNACIONAL\n\nCAPÍTULO I\n\nDOS REGIMES ADUANEIROS ESPECIAIS\n\nSeção IV\n\nDos Regimes de Aperfeiçoamento','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(202,'Art. 90. Fica suspenso o pagamento do IBS e da CBS incidentes na importação enquanto os bens materiais estiverem submetidos a regime aduaneiro especial de aperfeiçoamento, observada a disciplina estabelecida na legislação aduaneira.','Art. 90','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO II\n\nDOS REGIMES ADUANEIROS ESPECIAIS E DOS REGIMES DE BAGAGEM, DE REMESSAS INTERNACIONAIS E DE FORNECIMENTO DE COMBUSTÍVEL PARA AERONAVES EM TRÁFEGO INTERNACIONAL\n\nCAPÍTULO I\n\nDOS REGIMES ADUANEIROS ESPECIAIS\n\nSeção IV\n\nDos Regimes de Aperfeiçoamento','2026-01-01',NULL);
INSERT INTO FUNDAMENTACAO_LEGAL(FDLG_ID,FDLG_TEXTO,FDLG_TEXTO_CURTO,FDLG_REFERENCIA_NORMATIVA,FDLG_INICIO_VIGENCIA,FDLG_FIM_VIGENCIA) VALUES(203,'Art. 102. Aplica-se o tratamento estabelecido nos arts. 99 e 100 desta Lei Complementar às aquisições de máquinas, de aparelhos, de instrumentos, de equipamentos, de matérias-primas, de produtos intermediários e de materiais de embalagem realizadas entre empresas autorizadas a operar em zonas de processamento de exportação.','Art. 102','LIVRO I \n\nDO IMPOSTO SOBRE BENS E SERVIÇOS (IBS) E DA CONTRIBUIÇÃO SOCIAL SOBRE BENS E SERVIÇOS (CBS) \n\nTÍTULO II\n\nDOS REGIMES ADUANEIROS ESPECIAIS E DOS REGIMES DE BAGAGEM, DE REMESSAS INTERNACIONAIS E DE FORNECIMENTO DE COMBUSTÍVEL PARA AERONAVES EM TRÁFEGO INTERNACIONAL\n\nCAPÍTULO II\n\nDAS ZONAS DE PROCESSAMENTO DE EXPORTAÇÃO','2026-01-01',NULL);
