-- ==============================================
-- 3. Atualizações de Fundamentação Legal
-- ==============================================
-- 550011
UPDATE FUNDAMENTACAO_LEGAL
SET FDLG_TEXTO = 'Art. 93. Observada a disciplina estabelecida na legislação aduaneira, fica suspenso o pagamento do IBS e da CBS nas seguintes operações: \nIV - importação ou aquisição no mercado interno de matérias-primas, produtos intermediários e materiais de embalagem para ser utilizados integralmente no processo produtivo de produto final a ser fornecido a empresa que o destine às atividades a que se refere o inciso I deste caput (Repetro-Industrialização);\n§ 4º Fica também suspenso o pagamento do IBS e da CBS na importação ou na aquisição de bens no mercado interno por empresa denominada fabricante intermediário para a industrialização de produto intermediário a ser fornecido a empresa que o utilize no processo produtivo de que trata o inciso IV do caput deste artigo.',
    FDLG_TEXTO_CURTO = 'Art. 93, IV e Art. 93, § 4º'
WHERE FDLG_ID = 109;

-- 550014
UPDATE FUNDAMENTACAO_LEGAL
SET FDLG_TEXTO = 'Art. 99. As importações ou as aquisições no mercado interno de máquinas, de aparelhos, de instrumentos e de equipamentos realizadas por empresa autorizada a operar em zonas de processamento de exportação serão efetuadas com suspensão do pagamento do IBS e da CBS.\n Art. 100. As importações ou as aquisições no mercado interno de matérias-primas, de produtos intermediários e de materiais de embalagem realizadas por empresa autorizada a operar em zonas de processamento de exportação serão efetuadas com suspensão do pagamento do IBS e da CBS.',
    FDLG_TEXTO_CURTO = 'Arts. 99 e 100'
WHERE FDLG_ID = 112;

