-- =====================================================================
-- 5. Data de atualização de todas as Classificações Tributárias IBS/CBS
-- =====================================================================
-- CLTR_CD não é único (os códigos do Imposto Seletivo colidem com os do IBS/CBS): o alvo é
-- restrito às classificações do tributo CBS (TBTO_ID = 2).
UPDATE CLASSIFICACAO_TRIBUTARIA
SET CLTR_DATA_ATUALIZACAO = '2026-10-01'
WHERE EXISTS (
    SELECT 1
      FROM TRIBUTO_SITUACAO_TRIBUTARIA TST
     WHERE TST.TRST_SITR_ID = CLASSIFICACAO_TRIBUTARIA.CLTR_SITR_ID
       AND TST.TRST_TBTO_ID = 2
);
